contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to, uint256 value) public {
        require(to != address(0), "recipient must not be zero");

        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 senderBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 recipientBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;
        require(senderBefore >= value, "insufficient balance for successful transfer");

        bool reverted;
        c.transfer(to, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 senderAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 recipientAfter = c.balanceOf(to); if (__ESBMC_reverted()) return;

        assert(!reverted && senderAfter == senderBefore - value && recipientAfter == recipientBefore + value && supplyAfter == supplyBefore);
    }

    receive() external payable {}
}

